function batchBoxes(parent,exclude=new Set()){const groups=new Map();for(const m of [...parent.children]){if(!m.isMesh||m.geometry.type!=='BoxGeometry'||exclude.has(m))continue;const key=m.material.uuid;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m);}for(const list of groups.values()){if(list.length<2)continue;const inst=new THREE.InstancedMesh(new THREE.BoxGeometry(1,1,1),list[0].material,list.length);list.forEach((m,i)=>{const p=m.geometry.parameters;const tmp=new THREE.Object3D();tmp.position.copy(m.position);tmp.quaternion.copy(m.quaternion);tmp.scale.copy(m.scale).multiply(new THREE.Vector3(p.width,p.height,p.depth));tmp.updateMatrix();inst.setMatrixAt(i,tmp.matrix);parent.remove(m);m.geometry.dispose();});inst.castShadow=true;inst.receiveShadow=true;parent.add(inst);}}
